    created_by character varying(120),
    created_by_email character varying(254),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_drives_ctc_positive CHECK ((ctc > (0)::numeric)),
    CONSTRAINT ck_drives_max_backlogs CHECK (((max_backlogs IS NULL) OR (max_backlogs >= 0))),
    CONSTRAINT ck_drives_min_cgpa CHECK (((min_cgpa IS NULL) OR ((min_cgpa >= (0)::numeric) AND (min_cgpa <= (10)::numeric)))),
    CONSTRAINT ck_drives_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'OPEN'::character varying, 'FROZEN'::character varying, 'CLOSED'::character varying])::text[])))
);

