    class10 numeric(5,2),
    class12 numeric(5,2),
    backlogs integer DEFAULT 0 NOT NULL,
    skills character varying(60)[] DEFAULT '{}'::character varying[] NOT NULL,
    verification character varying(16) DEFAULT 'NOT_SUBMITTED'::character varying NOT NULL,
    locked boolean DEFAULT false NOT NULL,
    verified_by character varying(120),
    verified_by_email character varying(254),
    verified_at timestamp with time zone,
    submitted_at timestamp with time zone,
    revision_reason text,
    placement character varying(16) DEFAULT 'UNPLACED'::character varying NOT NULL,
    placed_company character varying(120),
    placed_drive_id character varying(32),
    proof jsonb DEFAULT '{}'::jsonb NOT NULL,
    default_resume_id character varying(32),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_students_backlogs CHECK ((backlogs >= 0)),
    CONSTRAINT ck_students_cgpa CHECK (((cgpa IS NULL) OR ((cgpa >= (0)::numeric) AND (cgpa <= (10)::numeric)))),
    CONSTRAINT ck_students_class10 CHECK (((class10 IS NULL) OR ((class10 >= (0)::numeric) AND (class10 <= (100)::numeric)))),
    CONSTRAINT ck_students_class12 CHECK (((class12 IS NULL) OR ((class12 >= (0)::numeric) AND (class12 <= (100)::numeric)))),
    CONSTRAINT ck_students_lock_requires_verified CHECK ((NOT (locked AND ((verification)::text <> 'VERIFIED'::text)))),
    CONSTRAINT ck_students_placement CHECK (((placement)::text = ANY ((ARRAY['UNPLACED'::character varying, 'PLACED'::character varying])::text[]))),
    CONSTRAINT ck_students_verification CHECK (((verification)::text = ANY ((ARRAY['NOT_SUBMITTED'::character varying, 'PENDING'::character varying, 'VERIFIED'::character varying, 'REVISION'::character varying, 'REJECTED'::character varying])::text[])))
);

