);

-- Name: v_student_profile_state; Type: VIEW; Schema: public; Owner: -

CREATE VIEW public.v_student_profile_state AS
 SELECT roll,
    name,
        CASE
            WHEN ((placement)::text = 'PLACED'::text) THEN 'POLICY_LOCKED'::text
            WHEN (((verification)::text = 'VERIFIED'::text) AND locked) THEN 'VERIFIED_LOCKED'::text
            WHEN ((verification)::text = 'PENDING'::text) THEN 'PENDING_VERIFICATION'::text
            WHEN (((verification)::text = 'REVISION'::text) AND (revision_reason ~~ 'Unfrozen%'::text)) THEN 'UNFROZEN_EDITING'::text
            WHEN ((verification)::text = ANY ((ARRAY['REVISION'::character varying, 'REJECTED'::character varying])::text[])) THEN 'REVISION_REQUIRED'::text
            ELSE 'DRAFT'::text
        END AS profile_state
   FROM public.students s;

